#!/usr/bin/env node
// Generated files (committed, so the CLI stays a single dependency-free file and the
// Worker needs no build step of its own):
//   cli/bin/mailmint.mjs                          ← cli/src/*.mjs + @agent-socket/sdk, one file
//   worker/src/vendor/agent-socket-sdk.client.js  ← @agent-socket/sdk (browser ESM, served at /assets/)
//   worker/src/vendor/socket-tools.client.js      ← cli/src/socket-tools.mjs (served at /assets/)
//
//   node scripts/build.mjs           # regenerate
//   node scripts/build.mjs --check   # fail if any generated file is stale (run by `npm test` and prepublish)
//
// Each output records a hash of its inputs, so --check needs no esbuild: it runs on any
// platform, even with node_modules installed for another OS (e.g. a Linux container's
// checkout used from macOS).
import { createHash } from "node:crypto";
import { chmodSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const HEADER = "// GENERATED by scripts/build.mjs — edit the sources, then run `node scripts/build.mjs`.\n";

const read = (rel) => readFileSync(join(root, rel), "utf8");
const sdkDir = "node_modules/@agent-socket/sdk";
const sdkInputs = [`${sdkDir}/package.json`, ...readdirSync(join(root, sdkDir, "dist")).filter((f) => f.endsWith(".js")).sort().map((f) => `${sdkDir}/dist/${f}`)];
const cliInputs = ["cli/src/cli.mjs", "cli/src/socket-tools.mjs", ...sdkInputs, "scripts/build.mjs"];

function inputHash(files) {
  const h = createHash("sha256");
  for (const f of files) h.update(f).update("\0").update(read(f)).update("\0");
  return h.digest("hex").slice(0, 16);
}

const targets = [
  { file: "cli/bin/mailmint.mjs", inputs: cliInputs, make: async () => (await bundle("cli/src/cli.mjs", "node")).replace(/^#!.*\n/m, ""), shebang: true },
  { file: "worker/src/vendor/agent-socket-sdk.client.js", inputs: [...sdkInputs, "scripts/build.mjs"], make: () => bundle(`${sdkDir}/dist/index.js`, "browser") },
  { file: "worker/src/vendor/socket-tools.client.js", inputs: ["cli/src/socket-tools.mjs", "scripts/build.mjs"], make: async () => read("cli/src/socket-tools.mjs") },
];

const stamp = (hash) => `// inputs-sha256: ${hash}\n`;

async function bundle(entry, platform) {
  const { build } = await import("esbuild");
  const out = await build({
    entryPoints: [join(root, entry)],
    bundle: true,
    format: "esm",
    platform,
    target: platform === "node" ? "node22" : "es2022",
    write: false,
    legalComments: "inline",
    logLevel: "silent",
  });
  return out.outputFiles[0].text;
}

let stale = 0;
for (const t of targets) {
  const path = join(root, t.file);
  const hash = inputHash(t.inputs);
  let current = "";
  try {
    current = readFileSync(path, "utf8");
  } catch {}
  if (current.includes(stamp(hash))) continue;
  if (check) {
    console.error(`stale: ${t.file} (run: node scripts/build.mjs)`);
    stale++;
    continue;
  }
  const content = (t.shebang ? "#!/usr/bin/env node\n" : "") + HEADER + stamp(hash) + (await t.make());
  writeFileSync(path, content);
  if (t.shebang) chmodSync(path, 0o755);
  console.log(`wrote ${t.file}`);
}
if (stale) process.exit(1);
